from flask import Flask, jsonify, abort
app = Flask(__name__)

@app.route('/api/risorse/<id>')
def get_risorsa(id):
    if id not in ['1', '2', '3']:
        abort(404, description='Risorsa non trovata')
    return jsonify({'id': id, 'nome': f'Risorsa {id}'})

